{"path":"fees.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investment — Sessions & Intensives</title>
  <style>
    :root{
      --bg:#0b1021;--card:#0f1724aa;--accent:#8ae6d2;--muted:#a9b0c3;--glass:rgba(255,255,255,0.06);
      --glass-2:rgba(255,255,255,0.03);--glass-border:rgba(255,255,255,0.08);
      --glass-radius:16px;--fw:400;--heading:700;--max:1100px;
    }
    *{box-sizing:border-box}
    html,body{height:100%;margin:0;background:linear-gradient(180deg,#071126 0%, #041022 100%);color:#e8eef6;font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;line-height:1.45}
    .page{min-height:100vh;display:flex;flex-direction:column;align-items:center;padding:28px}
    header{width:100%;max-width:var(--max);display:flex;align-items:center;justify-content:space-between;margin-bottom:22px}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:52px;height:52px;border-radius:12px;background:linear-gradient(135deg,#122433 0%,#163045 100%);box-shadow:0 6px 18px rgba(10,20,30,0.6);display:flex;align-items:center;justify-content:center;border:1px solid rgba(255,255,255,0.04)}
    .logo svg{width:34px;height:34px;filter:drop-shadow(0 6px 14px rgba(0,0,0,0.6))}
    nav{display:flex;gap:14px;align-items:center}
    nav a{color:var(--muted);text-decoration:none;padding:8px 12px;border-radius:10px;font-size:14px}
    nav a:hover{color:#fff;background:linear-gradient(90deg, rgba(255,255,255,0.03), transparent)}

    main{width:100%;max-width:var(--max);display:grid;grid-template-columns:1fr 360px;gap:20px}
    .hero{padding:28px;border-radius:var(--glass-radius);background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));backdrop-filter: blur(8px);border:1px solid var(--glass-border)}
    .hero h1{margin:0 0 6px 0;font-weight:700;font-size:22px;color:#eafaf6}
    .hero p{margin:0 0 16px 0;color:var(--muted)}
    .pill{display:inline-block;padding:6px 10px;border-radius:999px;background:linear-gradient(90deg, rgba(138,230,210,0.12), rgba(138,230,210,0.06));color:var(--accent);font-weight:600;font-size:13px}

    .card{background:var(--card);padding:18px;border-radius:14px;border:1px solid var(--glass-border)}
    .pricing{display:grid;grid-template-columns:repeat(1,1fr);gap:12px;margin-top:14px}
    .pkg{padding:14px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);display:flex;flex-direction:column;gap:8px;border:1px solid rgba(255,255,255,0.03)}
    .pkg h3{margin:0;font-size:16px}
    .price{font-weight:700;color:var(--accent);font-size:18px}
    .muted{color:var(--muted);font-size:14px}

    /* Mood-to-Method */
    .mood{display:flex;flex-direction:column;gap:12px}
    .mood select{appearance:none;padding:10px;border-radius:10px;border:1px solid var(--glass-border);background:transparent;color:#e9f6f0}
    .method{padding:12px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));border:1px dashed rgba(255,255,255,0.04)}
    .cta{display:inline-flex;align-items:center;gap:10px;padding:10px 14px;border-radius:12px;background:linear-gradient(90deg,var(--accent),#5ed7c1);color:#032024;font-weight:700;text-decoration:none;border:none;cursor:pointer}

    aside{position:relative}
    .note{color:var(--muted);font-size:13px}

    footer{width:100%;max-width:var(--max);margin-top:28px;color:var(--muted);font-size:13px}

    /* accordion */
    .accordion{margin-top:18px}
    .acc-item{border-top:1px solid rgba(255,255,255,0.02);padding:12px 0}
    .acc-head{display:flex;justify-content:space-between;align-items:center;cursor:pointer}
    .acc-body{max-height:0;overflow:hidden;transition:max-height .28s ease;padding-top:0}
    .acc-open .acc-body{padding-top:10px;max-height:600px}

    /* subtle animated pattern */
    .bg-pattern{position:absolute;inset:0;pointer-events:none;opacity:0.08}

    @media(max-width:880px){main{grid-template-columns:1fr}aside{order:-1}}
  </style>
</head>
<body>
  <div class="page">
    <header>
      <div class="brand">
        <div class="logo" aria-hidden>
          <svg viewBox="0 0 64 64" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="g" x1="0" x2="1"><stop offset="0" stop-color="#7ee6cf"/><stop offset="1" stop-color="#4cc5b8"/></linearGradient></defs><rect x="6" y="6" width="52" height="52" rx="12" fill="url(#g)" opacity="0.12"/><path d="M14 44c10-10 18-18 36-28" stroke="#9ff3e2" stroke-width="2.5" stroke-linecap="round" fill="none" opacity="0.9"/></svg>
        </div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div style="font-size:13px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Home</a>
        <a href="about.html">Why I Work</a>
        <a href="specialties.html">Focus Areas</a>
        <a href="approach.html">How I Work</a>
        <a href="fees.html">Investment</a>
        <a href="faq.html">Questions</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Get in Touch</a>
      </nav>
    </header>

    <main>
      <section class="hero card">
        <div class="pill">Intensive Offerings</div>
        <h1>Investment & pathways</h1>
        <p>Care arranged around concentrated time together — focused formats for change, stabilization, and transition. Sliding scale and single-session options are available; insurance is out-of-network (receipts provided).</p>

        <div class="pricing" aria-hidden>
          <div class="pkg">
            <div style="display:flex;justify-content:space-between;align-items:center">
              <h3>Anchor Session</h3>
              <div class="price">$160</div>
            </div>
            <div class="muted">75 minutes — best for an immediate assessment and plan.</div>
          </div>

          <div class="pkg">
            <div style="display:flex;justify-content:space-between;align-items:center">
              <h3>Deep-Dive Intensive</h3>
              <div class="price">$540</div>
            </div>
            <div class="muted">Three 75-minute sessions over 2–3 weeks; concentrated focus on a single problem or decision.</div>
          </div>

          <div class="pkg">
            <div style="display:flex;justify-content:space-between;align-items:center">
              <h3>Arc Package</h3>
              <div class="price">$1,050</div>
            </div>
            <div class="muted">Six sessions across ~12 weeks for short-term, goal-oriented work.</div>
          </div>
        </div>

        <div style="margin-top:16px;color:var(--muted);font-size:13px">I aim for clarity about fit, scope, and likely next steps in our first conversations. Numbers above are typical investments and do not reflect guarantees of outcome.</div>
      </section>

      <aside>
        <div class="card mood">
          <label style="font-size:13px;color:var(--muted)">Where are you right now?</label>
          <select id="moodSelect" aria-label="Select your current state">
            <option value="overwhelmed">Overwhelmed / scattered</option>
            <option value="stuck">Feeling stuck</option>
            <option value="grieving">Grieving / loss</option>
            <option value="anxious">Anxious / hypervigilant</option>
            <option value="ready">Ready to pivot</option>
          </select>

          <div class="method" id="methodBox">
            <strong id="methodTitle">Stabilization Protocol</strong>
            <div id="methodDesc" class="muted" style="margin-top:6px">A focused session plan to reduce immediate distress and outline next steps.</div>
          </div>

          <div style="display:flex;gap:10px;margin-top:12px">
            <button id="primaryCta" class="cta">Request Stabilization Call</button>
            <a href="{{PRIMARY_CTA_URL}}" id="secondaryLink" style="align-self:center;color:var(--muted);font-size:13px;text-decoration:none">Or email: {{EMAIL}}</a>
          </div>

          <div style="margin-top:12px" class="note">If you're considering urgent care, contact local emergency services or your nearest crisis line — see confidentiality notes below.</div>
        </div>

        <div class="card" style="margin-top:14px">
          <strong>Testimonials</strong>
          <div style="margin-top:10px;color:var(--muted);font-size:13px">"Attentive and direct — helped me make a plan when everything felt scattered." — A client in transition</div>
        </div>

        <svg class="bg-pattern" viewBox="0 0 600 200" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg" aria-hidden>
          <defs>
            <linearGradient id="p" x1="0" x2="1"><stop offset="0" stop-color="#5ed7c1" stop-opacity="0.14"/><stop offset="1" stop-color="#7ee6cf" stop-opacity="0.06"/></linearGradient>
          </defs>
          <path d="M0 100 Q120 40 240 100 T600 100 V200 H0z" fill="url(#p)"/>
        </svg>
      </aside>
    </main>

    <section class="card accordion" style="width:100%;max-width:var(--max);margin-top:18px">
      <h2 style="margin:0 0 10px 0">Session boundaries & confidentiality</h2>

      <div class="acc-item acc-open">
        <div class="acc-head">
          <div style="font-weight:600">Confidentiality and limits</div>
          <div style="color:var(--muted);font-size:13px">click to expand</div>
        </div>
        <div class="acc-body">
          <p class="muted">Sessions are confidential within legal and ethical limits. Exceptions include reasonable suspicion of child/elder/dependent adult abuse, imminent risk of serious harm to self or others, and court-ordered disclosure. Telehealth sessions follow the same privacy practices; I use secure platforms and maintain clinical records per professional standards.</p>
        </div>
      </div>

      <div class="acc-item">
        <div class="acc-head">
          <div style="font-weight:600">Scheduling & cancellation</div>
          <div style="color:var(--muted);font-size:13px">click to expand</div>
        </div>
        <div class="acc-body">
          <p class="muted">I ask for 48 hours notice for cancellations when possible. Late cancellations and no-shows may be billed at a portion of the session fee unless we agree otherwise. I will always work with you to find a fair solution when unexpected events arise.</p>
        </div>
      </div>

      <div class="acc-item">
        <div class="acc-head">
          <div style="font-weight:600">Scope of practice</div>
          <div style="color:var(--muted);font-size:13px">click to expand</div>
        </div>
        <div class="acc-body">
          <p class="muted">I provide psychotherapy and short-term intensives. I do not provide legal, financial, or forensic services. If you require services outside my scope, I will help identify appropriate referrals.</p>
        </div>
      </div>

      <div style="margin-top:12px;padding-top:12px;border-top:1px solid rgba(255,255,255,0.02);font-size:13px;color:var(--muted)">
        If you are in immediate danger or believe you may harm yourself or others, call local emergency services (911 in the U.S.) or contact your nearest crisis line. For confidential help in the U.S., you can call or text 988 to reach the Suicide & Crisis Lifeline. If outside the U.S., contact local emergency services or your national crisis resource.
      </div>
    </section>

    <footer>
      <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap">
        <div>&copy; <span id="year"></span> {{BUSINESS_NAME}} • <span style="color:var(--muted)">{{PHONE}}</span></div>
        <div style="color:var(--muted)">Privacy, limits, and scheduling details are discussed at intake.</div>
      </div>
    </footer>
  </div>

  <script>
    document.getElementById('year').textContent = new Date().getFullYear();

    // Mood-to-Method mapping
    const map = {
      overwhelmed: {title:"Stabilization Protocol", desc:"Short-term tools and a clear plan to reduce immediate distress and re-establish routine.", cta:"Request Stabilization Call"},
      stuck: {title:"Narrative Reframing Intensive", desc:"A concentrated plan to identify blocks and create small experiments toward change.", cta:"Request a Clarity Intensive"},
      grieving: {title:"Companion Sessions", desc:"Gentle, paced sessions to hold mourning and track needs in the weeks that follow.", cta:"Request Companion Session"},
      anxious: {title:"Symptom Stabilization Intensive", desc:"Focused interventions to reduce arousal and build reliable regulation strategies.", cta:"Request Stabilization Call"},
      ready: {title:"Transition Arc", desc:"Short-term, goal-oriented work to design practical steps for the change you want to start now.", cta:"Schedule a Planning Session"}
    };

    const moodSelect = document.getElementById('moodSelect');
    const methodTitle = document.getElementById('methodTitle');
    const methodDesc = document.getElementById('methodDesc');
    const primaryCta = document.getElementById('primaryCta');

    function applyMood(key){
      const m = map[key] || map['overwhelmed'];
      methodTitle.textContent = m.title;
      methodDesc.textContent = m.desc;
      primaryCta.textContent = m.cta;
      // animate
      const box = document.getElementById('methodBox');
      box.animate([{transform:'scale(1)'},{transform:'scale(1.02)'},{transform:'scale(1)'}],{duration:400});
      // set CTA behavior to carry a param to booking
      primaryCta.dataset.method = m.title;
    }

    moodSelect.addEventListener('change', e=>applyMood(e.target.value));
    applyMood(moodSelect.value);

    // CTA opens booking page with query param
    primaryCta.addEventListener('click', ()=>{
      const method = encodeURIComponent(primaryCta.dataset.method || 'Stabilization Protocol');
      const url = new URL('{{PRIMARY_CTA_URL}}', location.href);
      url.searchParams.set('preferred_program', method);
      url.searchParams.set('source','fees_page');
      window.location.href = url.toString();
    });

    // Accordion
    document.querySelectorAll('.acc-item').forEach(item=>{
      const head = item.querySelector('.acc-head');
      head.addEventListener('click', ()=>{
        item.classList.toggle('acc-open');
      });
    });
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Frequently Asked Questions</title>
  <style>
    :root{--bg:#071025;--muted:#9fb1c2;--glass-border:rgba(255,255,255,0.06);--accent:#7ee6cf}
    body{margin:0;font-family:Inter,system-ui,Arial;background:linear-gradient(180deg,#041021,#071126);color:#e6f7f2}
    .wrap{max-width:980px;margin:28px auto;padding:20px}
    header{display:flex;justify-content:space-between;align-items:center}
    header a{color:var(--muted);text-decoration:none;margin-left:12px}
    .hero{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:20px;border-radius:14px;border:1px solid var(--glass-border)}
    h1{margin:0 0 8px 0}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:18px}
    .card{background:rgba(15,23,36,0.6);padding:14px;border-radius:12px;border:1px solid var(--glass-border)}
    .q{margin-bottom:12px}
    .q summary{cursor:pointer;font-weight:700}
    details{background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);padding:10px;border-radius:10px;margin-bottom:8px;border:1px solid rgba(255,255,255,0.02)}
    .muted{color:var(--muted)}
    .mood{margin-top:10px}
    .mood select{width:100%;padding:10px;border-radius:10px;border:1px solid var(--glass-border);background:transparent;color:#e9fbf4}
    .method{margin-top:10px;padding:10px;border-radius:10px;border:1px dashed rgba(255,255,255,0.03)}
    footer{margin-top:18px;color:var(--muted);font-size:13px}
    @media(max-width:880px){.grid{grid-template-columns:1fr}}  
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
      <nav>
        <a href="index.html">Home</a>
        <a href="approach.html">How I Work</a>
        <a href="book.html">Reserve</a>
      </nav>
    </header>

    <section class="hero">
      <h1>Questions I hear most</h1>
      <p class="muted">Short answers to practical questions about sessions, access, and what to expect. These are meant to orient; we’ll discuss specifics during scheduling and intake.</p>
    </section>

    <div class="grid">
      <div>
        <details open class="card">
          <summary>How soon can I begin?</summary>
          <div class="muted" style="margin-top:8px">I aim to respond to booking requests within 48 business hours. Availability varies week-to-week; intensive formats can sometimes be scheduled more quickly when blocks align.</div>
        </details>

        <details class="card">
          <summary>Do you accept insurance?</summary>
          <div class="muted" style="margin-top:8px">I do not bill insurance directly. I provide a superbill — an itemized receipt you may submit to your carrier for out-of-network reimbursement. Coverage varies by plan.</div>
        </details>

        <details class="card">
          <summary>What is an intensive?</summary>
          <div class="muted" style="margin-top:8px">Intensives are a small set of longer or closely spaced sessions designed to address a particular problem or decision efficiently. They are not a guarantee of outcome, but a focused structure to clarify priorities and create a plan.</div>
        </details>

        <details class="card">
          <summary>Do you offer sliding scale?</summary>
          <div class="muted" style="margin-top:8px">A limited number of sliding-scale openings are available. If finances are a barrier, please mention this when you inquire so we can explore options or referrals.</div>
        </details>

        <details class="card">
          <summary>What if I need more than short-term work?</summary>
          <div class="muted" style="margin-top:8px">We will collaboratively assess needs and discuss ongoing care versus short-term work. I make referrals when longer-term or specialty services are a better fit.</div>
        </details>

        <details class="card">
          <summary>Privacy & limits</summary>
          <div class="muted" style="margin-top:8px">Your conversations are confidential except where required by law: imminent risk, certain abuse disclosures, or court orders. If you have concerns, we’ll review them during intake.</div>
        </details>
      </div>

      <aside>
        <div class="card">
          <strong>Quick navigator</strong>
          <div class="muted" style="margin-top:8px">Use the mood selector below to see which format I usually recommend for common states of mind. This helps you choose a booking path that fits your immediate need.</div>

          <div class="mood">
            <label class="muted" style="font-size:13px">Choose what feels closest:</label>
            <select id="moodSelectFaq">
              <option value="overwhelmed">Overwhelmed</option>
              <option value="stuck">Stuck</option>
              <option value="grieving">Grieving</option>
              <option value="anxious">Anxious</option>
              <option value="ready">Ready to pivot</option>
            </select>
            <div class="method" id="methodFaq"><strong id="mTitle">Stabilization Protocol</strong><div id="mDesc" class="muted" style="margin-top:6px">Short, practical steps to reduce distress and make a plan.</div></div>
            <a id="goBook" href="{{PRIMARY_CTA_URL}}" style="display:inline-block;margin-top:10px;padding:10px 12px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#5ed7c1);color:#022228;text-decoration:none;font-weight:700">Go to booking</a>
          </div>
        </div>

        <div class="card" style="margin-top:12px">
          <strong>Confidentiality & boundaries</strong>
          <p class="muted" style="margin-top:8px">Records are kept securely. Exceptions to confidentiality include harm to self or others, and suspicion of child/elder abuse. For emergencies, call local services or your regional crisis line.</p>
        </div>
      </aside>
    </div>

    <section style="margin-top:18px" class="card">
      <h3 style="margin:0 0 8px 0">Respectful crisis note</h3>
      <p class="muted">If you are thinking about harming yourself or someone else, please call local emergency services (911 in the U.S.) or contact your country’s emergency number. In the U.S., you can call or text 988 for the Suicide & Crisis Lifeline. If you are outside the U.S., please contact local emergency services or your national crisis resource. If you share this during hours when I am not available, I will help connect you to immediate care when I next speak with you.</p>
    </section>

    <footer>
      <div style="display:flex;justify-content:space-between;align-items:center;margin-top:18px">
        <div class="muted">Questions? Email <a href="mailto:{{EMAIL}}" style="color:#9fd6c8;text-decoration:none">{{EMAIL}}</a> or call {{PHONE}}</div>
        <div class="muted">© <span id="yr"></span> {{BUSINESS_NAME}}</div>
      </div>
    </footer>
  </div>

  <script>
    document.getElementById('yr').textContent = new Date().getFullYear();
    const mapping = {
      overwhelmed: ['Stabilization Protocol','Short tools to reduce immediate distress.'],
      stuck: ['Narrative Reframing Intensive','Three focused sessions to reframe obstacles and test small changes.'],
      grieving: ['Companion Sessions','Gentle pacing and holding while you adapt.'],
      anxious: ['Symptom Stabilization Intensive','Targeted strategies for lowering arousal and building regulation.'],
      ready: ['Transition Arc','A short series that helps you design and start new steps.']
    };

    const sel = document.getElementById('moodSelectFaq');
    function updateFaq(){
      const v = sel.value; const m = mapping[v];
      document.getElementById('mTitle').textContent = m[0];
      document.getElementById('mDesc').textContent = m[1];
      const goBook = document.getElementById('goBook');
      const url = new URL('{{PRIMARY_CTA_URL}}', location.href);
      url.searchParams.set('recommended', m[0]);
      goBook.href = url.toString();
    }
    sel.addEventListener('change', updateFaq);
    updateFaq();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve a Session</title>
  <style>
    :root{--bg:#051026;--glass:rgba(255,255,255,0.04);--accent:#7fe6d2;--muted:#9fb1c2}
    body{margin:0;font-family:Inter,system-ui,Arial;color:#eafbf7;background:linear-gradient(180deg,#041226,#071428)}
    .wrap{max-width:920px;margin:28px auto;padding:18px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{color:var(--muted);text-decoration:none;margin-left:10px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:18px;margin-top:16px}
    .card{background:rgba(18,26,38,0.6);padding:16px;border-radius:12px;border:1px solid rgba(255,255,255,0.04)}
    label{display:block;margin-top:8px;font-size:14px}
    input,textarea,select{width:100%;padding:10px;border-radius:10px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:#eafbf7}
    button{margin-top:12px;padding:10px 14px;border-radius:10px;border:none;background:linear-gradient(90deg,var(--accent),#4ccfbf);color:#052727;font-weight:700;cursor:pointer}
    .muted{color:var(--muted);font-size:13px}
    .program{padding:10px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border:1px solid rgba(255,255,255,0.03)}
    .conf{font-size:13px;color:var(--muted);margin-top:12px}
    @media(max-width:880px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div>
        <div style="font-weight:700">Reserve time — {{BUSINESS_NAME}}</div>
        <div class="muted">{{CITY}}, {{STATE}}</div>
      </div>
      <nav>
        <a href="index.html">Home</a>
        <a href="specialties.html">Focus Areas</a>
        <a href="fees.html">Investment</a>
      </nav>
    </header>

    <div class="grid">
