  <script>
    // Mapping for Mood-to-Method
    const map = {
      overwhelmed: {prog:'Stabilization Protocol',label:'Request Stabilization Call',desc:'Short-term tools to reduce immediate distress and build a brief plan.'},
      stuck: {prog:'Narrative Reframing Intensive',label:'Request a Clarity Intensive',desc:'A three-session cluster to break cycles and test small changes.'},
      grieving: {prog:'Companion Sessions',label:'Request Companion Session',desc:'Gentle sessions paced to support grief and adjustment.'},
      anxious: {prog:'Symptom Stabilization Intensive',label:'Request Stabilization Call',desc:'Targeted interventions to lessen arousal and build regulation skills.'},
      ready: {prog:'Transition Arc',label:'Schedule a Planning Session',desc:'A short series to design practical next steps and begin implementation.'}
    };

    const mood = document.getElementById('mood');
    const recTitle = document.getElementById('recTitle');
    const recDesc = document.getElementById('recDesc');
    const programField = document.getElementById('programField');
    const submitBtn = document.getElementById('submitBtn');
    const form = document.getElementById('bookForm');

    function apply(){
      const v = mood.value; const m = map[v];
      recTitle.textContent = m.prog;
      recDesc.textContent = m.desc;
      programField.value = m.prog;
      submitBtn.textContent = m.label;
      // gentle highlight
      document.getElementById('recommended').animate([{opacity:0.9},{opacity:1}],{duration:280});
    }
    mood.addEventListener('change', apply);
    apply();

    // Form submit behavior: send to PRIMARY_CTA_URL with query params for preview
    form.addEventListener('submit', function(e){
      // Build URL to redirect user to booking endpoint with form values in querystring.
      e.preventDefault();
      const data = new FormData(form);
      const url = new URL(form.action, location.href);
      for(const [k,v] of data.entries()){
        if(v) url.searchParams.append(k,v);
      }
      // open booking target (could be scheduling tool). Use location replace to avoid back button issues.
      window.location.href = url.toString();
    });
  </script>
